<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\ResultStorageService;
Auth::requireAdmin();$pdo=Database::connection();$userId=(int)(Auth::user()['id']??0);$roundId=(int)($_GET['round_id']??$_POST['round_id']??0);$error='';$notice='';
function salsaSuper():bool{try{if(method_exists(Auth::class,'isSuperAdmin')&&Auth::isSuperAdmin())return true;}catch(Throwable){}$u=Auth::user();$r=strtolower(str_replace(['-',' '],'_',trim((string)($u['role']??''))));return in_array($r,['super_admin','superadmin','owner','root','system_admin'],true)||!empty($u['is_super_admin']);}
function salsaOrdinal(int $n):string{if($n%100>=11&&$n%100<=13)return $n.'th';return $n.([1=>'st',2=>'nd',3=>'rd'][$n%10]??'th');}
function salsaPoints(int $tier,int $rank,int $count):float{$m=[1=>[1=>5,2=>4,3=>3,4=>2,5=>1],2=>[1=>10,2=>8,3=>6,4=>4,5=>2],3=>[1=>15,2=>12,3=>10,4=>8,5=>6]];if(isset($m[$tier][$rank]))return(float)$m[$tier][$rank];if($tier===2&&$rank>=6&&$rank<=10)return 1.0;if($tier===3&&$rank>=6&&$rank<=$count)return 2.0;return 0.0;}
function salsaAudit(PDO $pdo,int $roundId,int $userId,string $action,array $details=[]):void{$s=$pdo->prepare('INSERT INTO bdc_scoring_audit(round_id,user_id,action,details_json) VALUES(:r,:u,:a,:d)');$s->execute(['r'=>$roundId,'u'=>$userId?:null,'a'=>$action,'d'=>json_encode($details,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);}
function salsaRound(PDO $pdo,int $id):array{$s=$pdo->prepare("SELECT r.*,e.name event_name,e.event_date,e.venue FROM bdc_scoring_rounds r JOIN bdc_events e ON e.id=r.event_id WHERE r.id=:id AND r.round_type='final' AND r.dance_style='salsa' LIMIT 1");$s->execute(['id'=>$id]);$r=$s->fetch();if(!$r)throw new RuntimeException('Salsa Final round not found.');return $r;}
function salsaTier(PDO $pdo,array $round):array{$s=$pdo->prepare("SELECT points_tier FROM bdc_event_points_tiers WHERE event_id=:e AND dance_style='salsa' AND division=:d ORDER BY FIELD(dance_role,'both','leader','follower'),id LIMIT 1");$s->execute(['e'=>$round['event_id'],'d'=>$round['division']]);$tier=(int)$s->fetchColumn();if(in_array($tier,[1,2,3],true))return ['tier'=>$tier,'source'=>'Saved Salsa event/division tier'];$h=$pdo->prepare("SELECT id FROM bdc_scoring_rounds WHERE event_id=:e AND dance_style='salsa' AND division=:d AND round_type='heats' ORDER BY id ASC LIMIT 1");$h->execute(['e'=>$round['event_id'],'d'=>$round['division']]);$hid=(int)$h->fetchColumn();if($hid<1)throw new RuntimeException('Salsa Heats round not found. The BDC points tier cannot be determined.');$c=$pdo->prepare("SELECT MAX(role_total) FROM (SELECT COUNT(*) role_total FROM bdc_scoring_entries WHERE round_id=:r AND entry_status='active' GROUP BY dance_role) x");$c->execute(['r'=>$hid]);$count=(int)$c->fetchColumn();if($count<5)throw new RuntimeException('At least 5 competitors are required for a BDC points tier.');$tier=$count<=15?1:($count<=30?2:3);return ['tier'=>$tier,'source'=>'Automatically derived from '.$count.' Salsa Heats competitors'];}
function salsaPairs(PDO $pdo,int $roundId,int $tier):array{$s=$pdo->prepare("SELECT fp.id pair_id,fp.pair_number,le.competitor_id leader_competitor_id,le.display_name leader_name,le.bib_number leader_bib,fe.competitor_id follower_competitor_id,fe.display_name follower_name,fe.bib_number follower_bib,fr.final_rank FROM bdc_scoring_final_pairs fp JOIN bdc_scoring_entries le ON le.id=fp.leader_entry_id JOIN bdc_scoring_entries fe ON fe.id=fp.follower_entry_id JOIN bdc_scoring_final_results fr ON fr.round_id=fp.round_id AND fr.pair_id=fp.id WHERE fp.round_id=:r AND fp.pairing_status='confirmed' ORDER BY fr.final_rank");$s->execute(['r'=>$roundId]);$pairs=$s->fetchAll();if(!$pairs)throw new RuntimeException('Calculate and submit Final rankings before publication.');$count=count($pairs);foreach($pairs as &$p)$p['points']=salsaPoints($tier,(int)$p['final_rank'],$count);unset($p);return $pairs;}
function salsaPublication(PDO $pdo,int $roundId):?array{$s=$pdo->prepare('SELECT * FROM bdc_scoring_publications WHERE final_round_id=:r LIMIT 1');$s->execute(['r'=>$roundId]);return $s->fetch()?:null;}
function salsaSafe(string $s):string{$s=preg_replace('/[^A-Za-z0-9 _-]+/u','',$s)??'Event';return trim(preg_replace('/\s+/u',' ',$s)??'Event')?:'Event';}
function salsaHtml(PDO $pdo,array $round,array $pairs,int $tier):array{$root=ResultStorageService::root();if(!is_dir($root)&&!mkdir($root,0755,true)&&!is_dir($root))throw new RuntimeException('Could not create result repository folder.');$event=salsaSafe((string)$round['event_name']);$date=(string)($round['event_date']?:date('Y-m-d'));$division=ucfirst((string)$round['division']);$heats=$pdo->prepare("SELECT se.dance_role,se.bib_number,se.display_name,sr.rank_number,sr.result_status,sr.total_score FROM bdc_scoring_rounds r JOIN bdc_scoring_entries se ON se.round_id=r.id LEFT JOIN bdc_scoring_results sr ON sr.round_id=r.id AND sr.entry_id=se.id WHERE r.event_id=:e AND r.dance_style='salsa' AND r.division=:d AND r.round_type='heats' AND se.entry_status='active' ORDER BY se.dance_role,sr.rank_number,se.bib_number");$heats->execute(['e'=>$round['event_id'],'d'=>$round['division']]);$heatsRows=$heats->fetchAll();$head='<html><head><meta charset="utf-8"><style>body{font-family:Arial;padding:30px;color:#111}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ccc;padding:8px;text-align:left}h1{margin-bottom:4px}.meta{color:#666;margin-bottom:20px}</style></head><body><h1>'.htmlspecialchars((string)$round['event_name']).'</h1><div class="meta">SALSA · '.htmlspecialchars($division).' · '.htmlspecialchars($date).'</div>';$heatBody=$head.'<h2>Heats Results</h2><table><tr><th>Role</th><th>Bib</th><th>Competitor</th><th>Rank</th><th>Status</th><th>Score</th></tr>';foreach($heatsRows as $r)$heatBody.='<tr><td>'.htmlspecialchars(ucfirst((string)$r['dance_role'])).'</td><td>'.(int)$r['bib_number'].'</td><td>'.htmlspecialchars((string)$r['display_name']).'</td><td>'.htmlspecialchars((string)($r['rank_number']??'—')).'</td><td>'.htmlspecialchars((string)($r['result_status']??'—')).'</td><td>'.htmlspecialchars((string)($r['total_score']??'—')).'</td></tr>';$heatBody.='</table></body></html>';$finalBody=$head.'<h2>Final Results</h2><table><tr><th>Place</th><th>Leader</th><th>Follower</th></tr>';foreach($pairs as $p)$finalBody.='<tr><td>'.salsaOrdinal((int)$p['final_rank']).'</td><td>'.htmlspecialchars((string)$p['leader_name']).'</td><td>'.htmlspecialchars((string)$p['follower_name']).'</td></tr>';$finalBody.='</table></body></html>';$pointsBody=$head.'<h2>Final Ranking & Points</h2><div class="meta">BDC Tier '.$tier.'</div><table><tr><th>Place</th><th>Leader</th><th>Follower</th><th>Points Each</th></tr>';foreach($pairs as $p)$pointsBody.='<tr><td>'.salsaOrdinal((int)$p['final_rank']).'</td><td>'.htmlspecialchars((string)$p['leader_name']).'</td><td>'.htmlspecialchars((string)$p['follower_name']).'</td><td>'.(float)$p['points'].'</td></tr>';$pointsBody.='</table></body></html>';$files=[];foreach(['heats'=>$heatBody,'finals'=>$finalBody,'points'=>$pointsBody] as $cat=>$body){$name=$event.'_Salsa_'.$round['division'].'_'.ucfirst($cat).'_'.$date.'.html';$path=$root.'/'.$name;if(file_put_contents($path,$body)===false)throw new RuntimeException('Could not create Salsa '.$cat.' result file.');@chmod($path,0644);$files[$cat]=['name'=>$name,'path'=>$path,'relative'=>ResultStorageService::relative($name),'url'=>ResultStorageService::publicUrl($name)];}return $files;}
$isSuper=salsaSuper();
try{$round=salsaRound($pdo,$roundId);$tierInfo=salsaTier($pdo,$round);$tier=(int)$tierInfo['tier'];$pairs=salsaPairs($pdo,$roundId,$tier);$publication=salsaPublication($pdo,$roundId);if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$action=(string)($_POST['action']??'');if($action==='submit_for_approval'){if($round['status']!=='scores_submitted')throw new RuntimeException('Final scores must be submitted before requesting approval.');$pdo->beginTransaction();if($publication){$pdo->prepare("UPDATE bdc_scoring_publications SET points_tier=:tier,status='pending_approval',submitted_by=:u,submitted_at=NOW(),rejected_by=NULL,rejected_at=NULL,rejection_reason=NULL,updated_at=NOW() WHERE id=:id")->execute(['tier'=>$tier,'u'=>$userId?:null,'id'=>$publication['id']]);$publicationId=(int)$publication['id'];}else{$pdo->prepare("INSERT INTO bdc_scoring_publications(event_id,final_round_id,division,points_tier,status,submitted_by,submitted_at,published_at) VALUES(:e,:r,:d,:tier,'pending_approval',:u,NOW(),NULL)")->execute(['e'=>$round['event_id'],'r'=>$roundId,'d'=>$round['division'],'tier'=>$tier,'u'=>$userId?:null]);$publicationId=(int)$pdo->lastInsertId();}$pdo->prepare("UPDATE bdc_scoring_rounds SET status='pending_approval',publication_id=:p,locked_at=NOW(),locked_by=:u WHERE id=:r")->execute(['p'=>$publicationId,'u'=>$userId?:null,'r'=>$roundId]);salsaAudit($pdo,$roundId,$userId,'competition_submitted_for_approval',['publication_id'=>$publicationId,'dance_style'=>'salsa','points_tier'=>$tier]);$pdo->commit();$notice='Salsa competition submitted for Super Admin approval. No points have been written yet.';}
if($action==='approve_publication'){if(!$isSuper)throw new RuntimeException('Only Super Admin can approve publication.');$publication=salsaPublication($pdo,$roundId);if(!$publication||$publication['status']!=='pending_approval')throw new RuntimeException('No pending Salsa approval was found.');$files=salsaHtml($pdo,$round,$pairs,$tier);$pdo->beginTransaction();try{$pt=$pdo->prepare("INSERT INTO bdc_point_transactions(competitor_id,event_id,dance_style,division,dance_role,points,placement,notes,source_type,source_row_hash,created_by) VALUES(:c,:e,'salsa',:d,:role,:points,:place,:notes,'scoring_engine',:hash,:u)");$pr=$pdo->prepare("INSERT INTO bdc_participant_results(event_id,dance_style,competitor_id,division,dance_role,placement,finalist_status,partner_name,points_awarded,source,point_transaction_id) VALUES(:e,'salsa',:c,:d,:role,:place,:status,:partner,:points,'scoring_engine',:tx)");$link=$pdo->prepare("INSERT INTO bdc_scoring_publication_points(publication_id,pair_id,competitor_id,dance_role,final_rank,points_awarded,point_transaction_id,participant_result_id) VALUES(:p,:pair,:c,:role,:rank,:points,:tx,:result)");foreach($pairs as $pair){foreach([['role'=>'leader','c'=>(int)$pair['leader_competitor_id'],'partner'=>$pair['follower_name']],['role'=>'follower','c'=>(int)$pair['follower_competitor_id'],'partner'=>$pair['leader_name']]] as $person){if($person['c']<1)throw new RuntimeException('Every finalist must have a BDC ID.');$rank=(int)$pair['final_rank'];$points=(float)$pair['points'];$place=salsaOrdinal($rank);$hash=hash('sha256','salsa-scoring-publication|'.$publication['id'].'|'.$person['role'].'|'.$person['c']);$pt->execute(['c'=>$person['c'],'e'=>$round['event_id'],'d'=>$round['division'],'role'=>$person['role'],'points'=>$points,'place'=>$place,'notes'=>'BDC Salsa scoring publication #'.$publication['id'],'hash'=>$hash,'u'=>$userId?:null]);$tx=(int)$pdo->lastInsertId();$pr->execute(['e'=>$round['event_id'],'c'=>$person['c'],'d'=>$round['division'],'role'=>$person['role'],'place'=>$place,'status'=>$rank===1?'winner':($rank<=5?'placed':'finalist'),'partner'=>$person['partner'],'points'=>$points,'tx'=>$tx]);$result=(int)$pdo->lastInsertId();$link->execute(['p'=>$publication['id'],'pair'=>$pair['pair_id'],'c'=>$person['c'],'role'=>$person['role'],'rank'=>$rank,'points'=>$points,'tx'=>$tx,'result'=>$result]);}}
$doc=$pdo->prepare("INSERT INTO bdc_result_documents(event_id,title,document_category,file_type,url,storage_path,status,source,created_by) VALUES(:e,:title,:cat,'external',:url,:path,'published','scoring_engine',:u)");$map=$pdo->prepare("INSERT INTO bdc_scoring_publication_documents(publication_id,document_category,repository_document_id,storage_path) VALUES(:p,:cat,:doc,:path)");$docIds=[];foreach(['heats'=>'SALSA HEATS RESULTS','finals'=>'SALSA FINAL RESULTS','points'=>'SALSA FINAL RANKING & POINTS'] as $cat=>$title){$doc->execute(['e'=>$round['event_id'],'title'=>$title.' — '.$round['event_name'].' ('.ucfirst((string)$round['division']).')','cat'=>$cat,'url'=>$files[$cat]['url'],'path'=>$files[$cat]['relative'],'u'=>$userId?:null]);$docIds[$cat]=(int)$pdo->lastInsertId();$map->execute(['p'=>$publication['id'],'cat'=>$cat,'doc'=>$docIds[$cat],'path'=>$files[$cat]['relative']]);}$pdo->prepare("UPDATE bdc_scoring_publications SET status='published',repository_document_id=:doc,report_url=:url,published_by=:u,approved_by=:u,approved_at=NOW(),published_at=NOW(),updated_at=NOW() WHERE id=:p")->execute(['doc'=>$docIds['finals'],'url'=>$files['points']['url'],'u'=>$userId?:null,'p'=>$publication['id']]);$pdo->prepare("UPDATE bdc_events SET status='completed',updated_at=NOW() WHERE id=:e")->execute(['e'=>$round['event_id']]);$pdo->prepare("UPDATE bdc_scoring_rounds SET status='archived',published_document_id=:doc,locked_at=NOW(),locked_by=:u WHERE id=:r")->execute(['doc'=>$docIds['finals'],'u'=>$userId?:null,'r'=>$roundId]);salsaAudit($pdo,$roundId,$userId,'competition_approved_and_published',['publication_id'=>$publication['id'],'dance_style'=>'salsa','points_tier'=>$tier]);$pdo->commit();$notice='Salsa competition approved. Salsa points and repository results were published.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();foreach($files??[] as $f)if(is_file($f['path']))@unlink($f['path']);throw $e;}}
if($action==='reject_approval'){if(!$isSuper)throw new RuntimeException('Only Super Admin can reject an approval request.');$reason=trim((string)($_POST['reason']??''));if($reason==='')throw new RuntimeException('Rejection reason is required.');$publication=salsaPublication($pdo,$roundId);if(!$publication||$publication['status']!=='pending_approval')throw new RuntimeException('No pending approval found.');$pdo->beginTransaction();$pdo->prepare("UPDATE bdc_scoring_publications SET status='rejected',rejected_by=:u,rejected_at=NOW(),rejection_reason=:reason,updated_at=NOW() WHERE id=:p")->execute(['u'=>$userId?:null,'reason'=>$reason,'p'=>$publication['id']]);$pdo->prepare("UPDATE bdc_scoring_rounds SET status='scores_submitted',locked_at=NULL,locked_by=NULL WHERE id=:r")->execute(['r'=>$roundId]);salsaAudit($pdo,$roundId,$userId,'competition_approval_rejected',['publication_id'=>$publication['id'],'dance_style'=>'salsa','reason'=>$reason]);$pdo->commit();$notice='Salsa approval rejected. Final scoring is reopened.';}}
$round=salsaRound($pdo,$roundId);$publication=salsaPublication($pdo,$roundId);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();$round=$round??null;$pairs=$pairs??[];$publication=$publication??null;$tier=$tier??0;$tierInfo=$tierInfo??['source'=>''];}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Salsa Publication | BDC Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="index.php?round_id=<?=$roundId?>">BDC Scoring</a><span class="navbar-text text-white">SALSA PUBLICATION</span></div></nav><main class="container py-4" style="max-width:1000px"><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?><?php if($notice):?><div class="alert alert-success"><?=htmlspecialchars($notice)?></div><?php endif;?><?php if($round):?><div class="card shadow-sm mb-4"><div class="card-body"><div class="text-uppercase text-danger fw-bold small">Salsa</div><h1 class="h3 mb-1"><?=htmlspecialchars((string)$round['event_name'])?></h1><div class="text-muted"><?=htmlspecialchars(ucfirst((string)$round['division']))?> · BDC Tier <?=$tier?> · <?=htmlspecialchars((string)($tierInfo['source']??''))?></div></div></div><div class="card shadow-sm mb-4"><div class="card-body"><h2 class="h5">Final Ranking & Points</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Place</th><th>Leader</th><th>Follower</th><th>Points Each</th></tr></thead><tbody><?php foreach($pairs as $p):?><tr><td><?=salsaOrdinal((int)$p['final_rank'])?></td><td><?=htmlspecialchars((string)$p['leader_name'])?></td><td><?=htmlspecialchars((string)$p['follower_name'])?></td><td><strong><?=(float)$p['points']?></strong></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="card shadow-sm"><div class="card-body"><?php $status=(string)($publication['status']??'not_submitted');?><h2 class="h5">Publication Status: <?=htmlspecialchars(ucwords(str_replace('_',' ',$status)))?></h2><?php if(in_array($status,['not_submitted','rejected'],true)&&$round['status']==='scores_submitted'):?><form method="post"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><button class="btn btn-primary" name="action" value="submit_for_approval" onclick="return confirm('Submit this Salsa competition for Super Admin approval? No points are written until approval.')">Submit for Approval</button></form><?php elseif($status==='pending_approval'&&$isSuper):?><div class="d-flex gap-2 flex-wrap"><form method="post"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><button class="btn btn-success" name="action" value="approve_publication" onclick="return confirm('Approve and publish these Salsa results and Salsa points?')">Approve & Publish Salsa</button></form><form method="post" class="d-flex gap-2"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(Csrf::token())?>"><input type="hidden" name="round_id" value="<?=$roundId?>"><input class="form-control" name="reason" placeholder="Rejection reason" required><button class="btn btn-outline-danger" name="action" value="reject_approval">Reject</button></form></div><?php elseif($status==='pending_approval'):?><div class="alert alert-warning mb-0">Waiting for Super Admin approval. No Salsa points have been written yet.</div><?php elseif($status==='published'):?><div class="alert alert-success mb-0">Published. All points on this publication were written to the <strong>Salsa</strong> ledger only.</div><?php endif;?></div></div><?php endif;?></main></body></html>